def run(): # Validate native recovery, gradients and physically meaningful perturbations before any training use.
    started=time.monotonic();out=Path(__file__).parent;index_path=OLD_REPO/'build/complex-nonlinear-20261024/rebar/full27/index.json';index=json.loads(index_path.read_text());row=next(item for item in index['cases'] if item['split']=='train' and item['group_id']=='rebar_group_00');physics=RebarPhysics.from_case(row['npz']);data=np.load(row['npz']);states=torch.tensor(data['states'],dtype=torch.float64);native_rows=[];torch_rows=[] # Restrict verification to an already exposed original training group, not any V2 test or OOD truth.
